%[text] %[text:anchor:T_1FFD3858] # Longitudinal Vehicle - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Constant
model_name = "HarnessModel_Vehicle1D";
load_system(model_name)

Vehicle1D_Basic_params

loadLUTData_Vehicle1D_Zero

initial.vehicle_speed_kph = 0;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, model_name + "/Inputs", ReferencedSubsystem = "Inputs_Vehicle1D_LookupTables_refsub");
sim_in = setBlockParameter(sim_in, model_name + "/Longitudinal Vehicle", ReferencedSubsystem = "Vehicle1D_Basic_refsub");
sim_in = setModelParameter(sim_in, StopTime = "1000");
applyToModel(sim_in)
sim_out = sim(sim_in);

result = extractTimetable(sim_out.logsout);

signal_names = [
  "Axle torque input"
  "Brake force"
  "Road inclination"
  "Road grade"
  "G force"
  "Vehicle speed kph"
  "Vehicle speed mph"
  "Axle speed"
  ];

for k = 1 : numel(signal_names) %[output:group:123d287e]
  fig = bevutil1.SignalUtil.plotTimedData(TimedData = result, SignalName = signal_names(k)); %[output:35e70a49] %[output:7aaf05cd] %[output:797fc985] %[output:8facd5ff] %[output:9830c6fc] %[output:65d43768] %[output:82b92f41] %[output:3f5baa28]
  fig.Position(4) = 100;  % height
end  % for %[output:group:123d287e]
